/* globals $ */
/**
 * @ignore
 * @throws {Error} if mediawiki message is in unexpected format.
 * @return {jQuery.Object} a list of links
 */
const getLinks = () => {
	const mobileLicense = mw.message( 'mobile-frontend-license-links' );
	const mobileMsgExists = mobileLicense.exists() && mobileLicense.text();
	const userLanguage = mw.config.get( 'wgUserLanguage' );
	if ( userLanguage === 'qqx' ) {
		// Special handling for qqx code so we can easily debug what's going on here.
		return mobileLicense.parseDom();
	} else {
		return mobileMsgExists ? mobileLicense.parseDom() : $( 'body #footer-info-copyright a' ).clone();
	}
};

/**
 * Returns the appropriate license message including links/name to
 * terms of use (if any) and license page
 *
 * @ignore
 * @return {string|undefined}
 */
const getLicenseMessage = () => {
	const $licenseLinks = getLinks();

	let licenseMsg;
	if ( $licenseLinks.length ) {
		const licensePlural = mw.language.convertNumber(
			$licenseLinks.filter( 'a' ).length
		);

		if ( $( 'body #footer-places-terms-use' ).length > 0 ) {

			const $termsLink = mw.message(
				'mobile-frontend-editor-terms-link',
				$( 'body #footer-places-terms-use a' ).attr( 'href' )
			).parseDom();
			licenseMsg = mw.message(
				'mobile-frontend-editor-licensing-with-terms',
				$termsLink,
				$licenseLinks,
				licensePlural
			).parse();
		} else {
			licenseMsg = mw.message(
				'mobile-frontend-editor-licensing',
				$licenseLinks,
				licensePlural
			).parse();
		}
	}

	return licenseMsg;
};

module.exports = getLicenseMessage;
const
	HTML = mw.html,
	util = require( './util' );

/**
 * Mobile page view object
 */
class Page {
	/**
	 * @param {Object} options Configuration options
	 * @param {number} options.id Page ID. The default value of 0 represents a
	 * new or missing page. Be sure to override it to avoid side effects.
	 * @param {string} options.title Title of the page. It includes prefix where needed and
	 * is human readable, e.g. Talk:The man who lived.
	 * @param {Object} options.titleObj
	 * @param {string} options.displayTitle HTML title of the page for display. Falls back
	 * to defaults.title (escaped) if no value is provided. Must be safe HTML!
	 * @param {number} options.namespaceNumber the number of the
	 *  namespace the page belongs to
	 * @param {Object} options.protection List of permissions as returned by API,
	 * e.g. [{ edit: ['*'] }]
	 * @param {string} options.url
	 * @param {string} options.wikidataDescription
	 * @param {boolean} options.isMainPage Whether the page is the Main Page.
	 * @param {boolean} options.isMissing Whether the page exists in the wiki.
	 * @param {string} options.anchor
	 * @param {string} [options.relevantTitle] associated with page.
	 *  For example Special:WhatLinksHere/Foo would be associated with the page `Foo`.
	 * @param {number} options.revId  Revision ID. See `wgRevisionId`.
	 * @param {Object} options.thumbnail thumbnail definition corresponding to page image
	 * @param {boolean} options.thumbnail.isLandscape whether the image is in
	 *  landscape format
	 * @param {number} options.thumbnail.width of image in pixels.
	 * @param {number} options.thumbnail.height of image in pixels.
	 * @param {string} options.thumbnail.source url for image
	 */
	constructor( options ) {
		const title = options.title || '';
		util.extend( this, {
			id: options.id || 0,
			// FIXME: Deprecate title property as it can be derived from titleObj
			// using getPrefixedText
			title,
			relevantTitle: options.relevantTitle || title,
			titleObj: options.titleObj,
			displayTitle: options.displayTitle || HTML.escape( title ),
			namespaceNumber: options.namespaceNumber || 0,
			protection: options.protection,
			url: options.url || mw.util.getUrl( title ),
			wikidataDescription: options.wikidataDescription,
			_isMainPage: options.isMainPage || false,
			isMissing: ( options.isMissing !== undefined ) ?
				options.isMissing : options.id === 0,
			anchor: options.anchor,
			revId: options.revId,
			thumbnail: ( Object.prototype.hasOwnProperty.call( options, 'thumbnail' ) ) ?
				options.thumbnail : false
		} );

		if ( this.thumbnail && this.thumbnail.width ) {
			this.thumbnail.isLandscape = this.thumbnail.width > this.thumbnail.height;
		}
	}

	/**
	 * Retrieve the title that should be displayed to the user
	 *
	 * @return {string} HTML
	 */
	getDisplayTitle() {
		return this.displayTitle;
	}

	/**
	 * Determine if current page is in a specified namespace
	 *
	 * @param {string} namespace Name of namespace
	 * @return {boolean}
	 */
	inNamespace( namespace ) {
		return this.namespaceNumber === mw.config.get( 'wgNamespaceIds' )[namespace];
	}

	/**
	 * Determines if content model is wikitext
	 *
	 * @return {boolean}
	 */
	isWikiText() {
		return mw.config.get( 'wgPageContentModel' ) === 'wikitext';
	}

	/**
	 * Check if the visual editor is available on this page
	 *
	 * @return {boolean}
	 */
	isVEAvailable() {
		return !!mw.config.get( 'wgVisualEditorConfig' ) &&
			!mw.config.get( 'wgVisualEditorDisabledByHook' ) &&
			this.isWikiText();
	}

	/**
	 * Check if the visual editor in visual mode is available on this page
	 *
	 * @return {boolean}
	 */
	isVEVisualAvailable() {
		if ( !this.isVEAvailable() ) {
			return false;
		}
		const config = mw.config.get( 'wgVisualEditorConfig' );
		const visualEditorNamespaces = config.namespaces || [];

		return visualEditorNamespaces.includes( mw.config.get( 'wgNamespaceNumber' ) );
	}

	/**
	 * Check if the visual editor in source mode is available on this page
	 *
	 * @return {boolean}
	 */
	isVESourceAvailable() {
		return this.isVEAvailable() &&
			mw.config.get( 'wgMFEnableVEWikitextEditor' );
	}

	/**
	 * Checks whether the current page is the main page
	 *
	 * @return {boolean}
	 */
	isMainPage() {
		return this._isMainPage;
	}

	/**
	 * Return the latest revision id for this page
	 *
	 * @return {number}
	 */
	getRevisionId() {
		return this.revId;
	}

	/**
	 * Return prefixed page title
	 *
	 * @return {string}
	 */
	getTitle() {
		return this.title;
	}

	/**
	 * return namespace id
	 *
	 * @return {number} namespace Number
	 */
	getNamespaceId() {
		let nsId;
		const args = this.title.split( ':' );

		if ( args[1] ) {
			nsId = mw.config.get( 'wgNamespaceIds' )[ args[0].toLowerCase().replace( ' ', '_' ) ] || 0;
		} else {
			nsId = 0;
		}
		return nsId;
	}
}

module.exports = Page;
const
	Page = require( './Page' );

let page;

/**
 * Constructs an incomplete Page model singleton representing the currently loaded page.
 *
 * Because this depends on the presence of certain DOM elements, it
 * should only be called after the DOMContentLoaded event.
 *
 * @ignore
 * @return {Page}
 */
function loadCurrentPage() {
	if ( page ) {
		return page;
	}

	const permissions = [].concat( mw.config.get( 'wgRestrictionEdit', [] ) ),
		relevantTitle = mw.Title.newFromText( mw.config.get( 'wgRelevantPageName' ) ),
		title = mw.Title.newFromText( mw.config.get( 'wgPageName' ) );

	if ( permissions.length === 0 ) {
		permissions.push( '*' );
	}

	page = new Page( {
		title: title.getPrefixedText(),
		titleObj: title,
		relevantTitle: relevantTitle.getPrefixedText(),
		protection: {
			edit: permissions
		},
		revId: mw.config.get( 'wgRevisionId' ),
		isMainPage: mw.config.get( 'wgIsMainPage' ),
		id: mw.config.get( 'wgArticleId' ),
		namespaceNumber: mw.config.get( 'wgNamespaceNumber' )
	} );

	return page;
}

module.exports = loadCurrentPage;
const currentPageHTMLParser = require( './currentPageHTMLParser' );
const time = require( './time' );
const currentPage = require( './currentPage' );
const Drawer = require( './Drawer' );
const CtaDrawer = require( './CtaDrawer' );
const icons = require( './icons' );
const PageHTMLParser = require( './PageHTMLParser' );
const { showOnPageReload } = require( './showOnPageReload' );
const OverlayManager = require( './OverlayManager' );
const View = require( './View' );
const Overlay = require( './Overlay' );
const references = require( './references/references' );
const promisedView = require( './promisedView' );
const headers = require( './headers' );
const util = require( './util.js' );
const Icon = require( './Icon.js' );
const IconButton = require( './IconButton.js' );
const Button = require( './Button.js' );

// Expose chunk to temporary variable which will be deleted and exported via ResourceLoader
// package inside mobile.startup.exports.

/**
 * The main library for accessing MobileFrontend's stable APIs.
 *
 * @module mobile.startup
 */
module.exports = {
	/**
	 * Internal, strictly for use inside MobileFrontend only
	 *
	 * @memberof module:mobile.startup
	 * @type module:mobile.startup/util
	 * @private
	 */
	util,
	/**
	 * @private
	 */
	headers,
	// Internal for use inside GrowthExperiments only.
	overlayHeader: headers.header,
	/**
	 * Internal for use inside Minerva, GrowthExperiments only.
	 *
	 * @type module:mobile.startup/Drawer
	 */
	Drawer,
	// Internal for use inside Minerva only.
	CtaDrawer,
	/**
	 * @internal for use strictly inside MobileFrontend only. Other extensions
	 *  should use View.make and Overlay.make
	 */
	class: {
		View,
		Overlay,
		Icon,
		IconButton,
		Button
	},
	/**
	 * @stable for use
	 * @memberof module:mobile.startup
	 * @type module:mobile.startup/View
	 */
	View: {
		make: View.make
	},
	/**
	 * @stable for use
	 * @memberof module:mobile.startup
	 * @type module:mobile.startup/Overlay
	 */
	Overlay: {
		make: Overlay.make
	},
	/**
	 * Internal for use inside Minerva only.
	 *
	 * @memberof module:mobile.startup
	 * @type module:mobile.startup/PageHTMLParser
	 */
	currentPageHTMLParser,
	/**
	 * Internal for use inside Minerva, ExternalGuidance and Echo only.
	 *
	 * @memberof module:mobile.startup
	 * @return {module:mobile.startup/OverlayManager}
	 */
	getOverlayManager: () => OverlayManager.getSingleton(),
	/**
	 * Internal for use inside Minerva only.
	 *
	 * @type module:mobile.startup/Page
	 * @memberof module:mobile.startup
	 */
	currentPage,
	/**
	 * Internal for use inside Minerva only.
	 *
	 * @type module:mobile.startup/PageHTMLParser
	 * @memberof module:mobile.startup
	 */
	PageHTMLParser,
	/**
	 * Internal for use inside Minerva only.
	 *
	 * @type module:mobile.startup/Icon
	 * @memberof module:mobile.startup
	 */
	spinner: icons.spinner,
	/**
	 * Internal for use inside MobileFrontend only
	 *
	 * @private
	 */
	cancelIcon: icons.cancel,
	/**
	 * Internal for use inside Minerva only.
	 *
	 * @memberof module:mobile.startup
	 * @type module:mobile.startup/references
	 */
	references,
	/**
	 * Internal for use inside Minerva only.
	 *
	 * @memberof module:mobile.startup
	 * @type module:mobile.startup/time
	 */
	time,
	// Internal for use inside Echo, GrowthExperiments only.
	promisedView,
	/**
	 * Loads all images on the page, stable to call.
	 *
	 * @memberof module:mobile.startup
	 * @return {jQuery.Deferred}
	 */
	loadAllImagesInPage: () => {
		mw.log.deprecated(
			'[1.47.0] deprecated. Please rewrite loading attribute of all images in page'
		);
	},
	/**
	 * Show a notification on page reload, internal for Minerva
	 *
	 * @memberof module:mobile.startup
	 * @param {string} msg
	 * @return {jQuery.Deferred}
	 */
	notifyOnPageReload: ( msg ) => showOnPageReload( msg ),
	/**
	 * Internal for use inside VisualEditor
	 *
	 * @memberof module:mobile.startup
	 * @return {string|undefined}
	 */
	license() {
		mw.log.warn( `[deprecated] Please update your call to
			require('mobile.editor.overlay').getLicenseMessage` );
		return require( '../mobile.editor.overlay/getLicenseMessage.js' )();
	}
};
const
	icons = require( './icons' ),
	View = require( './View' );

/**
 * Internal for use inside Echo, GrowthExperiments only.
 * It's a view that spins until the promise resolves!
 * If the promise successfully resolves, the newView will be shown. if the
 * promise rejects and rejects to a view, the errorView will be shown.
 *
 * @function promisedView
 * @memberof module:mobile.startup
 * @param {jQuery.Promise} promise
 * @return {module:mobile.startup/View}
 */
module.exports = function promisedView( promise ) {
	const view = new View( {
		className: 'promised-view'
	} );
	view.$el.append( icons.spinner().$el );
	promise.then( ( newView ) => {
		view.$el.replaceWith( newView.$el );
		// update the internal reference.
		view.$el = newView.$el;
	}, ( errorView ) => {
		if ( !errorView || !errorView.$el ) {
			// return early to keep backwards compatibility with clients of
			// promisedView that do not reject to an error view
			return;
		}

		view.$el.replaceWith( errorView.$el );
		// update the internal reference.
		view.$el = errorView.$el;
	} );

	return view;
};
/**
 * Abstract base class
 * Gateway for retrieving references
 *
 * @class module:mobile.startup/references~Gateway
 * @abstract
 */
class ReferencesGateway {
	/**
	 * @param {mw.Api} api
	 */
	constructor( api ) {
		this.api = api;
	}

	// eslint-disable-next-line jsdoc/require-returns-check
	/**
	 * Return the matched reference via API or DOM query
	 *
	 * @memberof module:mobile.startup/references~Gateway
	 * @instance
	 * @param {string} id CSS selector
	 * @param {Page} page to find reference for
	 * @param {module:mobile.startup/PageHTMLParser} pageHTMLParser
	 * @return {jQuery.Promise} resolves with an Object representing reference
	 *  with a `text` property
	 *  The promise should be rejected with ReferenceGateway.ERROR_NOT_EXIST:
	 *  if the reference is not found.
	 *  If for some reason locating the reference fails return ReferenceGateway.ERROR_OTHER.
	 */
	// eslint-disable-next-line no-unused-vars
	getReference( id, page, pageHTMLParser ) {
		// overridden
	}
}

/**
 * @memberof module:mobile.startup/references~Gateway
 * @property ERROR_NOT_EXIST error code to be returned by getReference
 *  when a reference does not exist.
 * @type string
 */
ReferencesGateway.ERROR_NOT_EXIST = 'NOT_EXIST_ERROR';
/**
 * ERROR_OTHER error code to be returned by getReference
 *  under any other circumstance not covered
 *  by ERROR_NOT_EXIST. It should be used if it is unclear whether a reference exists or not.
 *
 * @memberof module:mobile.startup/references~Gateway
 * @type string
 */
ReferencesGateway.ERROR_OTHER = 'OTHER_ERROR';

module.exports = ReferencesGateway;
const ReferencesGateway = require( './ReferencesGateway' ),
	util = require( './../util' );

/**
 * Gateway for retrieving references via the content of the Page
 *
 * @memberof module:mobile.startup/references
 * @inheritdoc
 */
class ReferencesHtmlScraperGateway extends ReferencesGateway {
	constructor() {
		super( arguments );
		/**
		 * @memberof ReferencesHtmlScraperGateway
		 * @property EXTERNAL_LINK_CLASS a CSS class to place on external links
		 * in addition to the default 'external' class.
		 */
		this.EXTERNAL_LINK_CLASS = 'external--reference';
	}

	/**
	 * @param {string} id ID of a DOM element in the page.
	 * @param {jQuery.Object} $container to scan for an element
	 * @return {jQuery.Promise} that can be used by getReference
	 */
	getReferenceFromContainer( id, $container ) {
		const result = util.Deferred();

		const $el = $container.find( '#' + util.escapeSelector( id ) );
		if ( $el.length ) {
			let $parent;

			// This finds either the inner <ol class="mw-extended-references">, or the outer
			// <ol class="references">
			const $ol = $el.closest( 'ol' );
			const isSubref = $ol.hasClass( 'mw-subreference-list' );
			if ( isSubref ) {
				$parent = $ol.parent();
			}
			// The following classes are used here:
			// * external--reference
			// * other values of EXTERNAL_LINK_CLASS in sub-classes
			( $parent || $el ).find( '.external' ).addClass( this.EXTERNAL_LINK_CLASS );
			result.resolve( {
				text: this.getReferenceHtml( $el ),
				parentText: this.getReferenceHtml( $parent ),
				isSubref
			} );
		} else {
			result.reject( ReferencesGateway.ERROR_NOT_EXIST );
		}
		return result.promise();
	}

	/**
	 * @memberof ReferencesHtmlScraperGateway
	 * @param {jQuery.Object|undefined} $reference
	 * @return {string|undefined}
	 */
	getReferenceHtml( $reference ) {
		return $reference ?
			$reference.children( '.mw-reference-text, .reference-text' ).first().html() :
			'';
	}

	/**
	 * @inheritdoc
	 * @param {string} hash Hash fragment with leading '#'
	 * @param {Page} page (unused)
	 * @param {module:mobile.startup/PageHTMLParser} pageHTMLParser
	 */
	getReference( hash, page, pageHTMLParser ) {
		const id = mw.util.percentDecodeFragment( hash.slice( 1 ) );
		// If an id is not found it's possible the id passed needs decoding (per T188547).
		return this.getReferenceFromContainer( id, pageHTMLParser.$el.find( 'ol.references' ) );
	}
}

module.exports = ReferencesHtmlScraperGateway;
const Drawer = require( '../Drawer' ),
	util = require( '../util' ),
	icons = require( '../icons' ),
	ReferencesGateway = require( './ReferencesGateway' ),
	Icon = require( '../Icon' ),
	ReferencesHtmlScraperGateway = require( './ReferencesHtmlScraperGateway' ),
	IconButton = require( '../IconButton' );

/**
 * Create a callback for clicking references
 *
 * @ignore
 * @param {Function} onNestedReferenceClick
 * @return {Function}
 */
function makeOnNestedReferenceClickHandler( onNestedReferenceClick ) {
	return ( ev ) => {
		const target = ev.currentTarget.querySelector( 'a' );
		if ( target ) {
			onNestedReferenceClick(
				target.getAttribute( 'href' ),
				target.textContent
			);
			// Don't hide the already shown drawer via propagation
			return false;
		}
	};
}

/**
 * Drawer for references
 *
 * @memberof module:mobile.startup/references
 * @uses IconButton
 * @param {Object} props
 * @param {boolean} [props.error] whether an error has occurred
 * @param {string} props.title of reference e.g [1]
 * @param {string} props.text is the HTML of the reference
 * @param {string} [props.parentText] is the HTML of the parent reference if there is one
 * @param {boolean} props.isSubref true when this reference has a parent
 * @param {Function} [props.onNestedReferenceClick] callback for when a reference
 *  inside the reference is clicked.
 * @return {module:mobile.startup/Drawer}
 */
function referenceDrawer( props ) {
	const errorIcon = props.error ? new IconButton( {
		name: 'error',
		isSmall: true
	} ).$el : null;

	const mainRef = props.isSubref ? props.parentText : props.text;
	const mainRefHtml = util.parseHTML( '<div>' )
		.addClass( 'main-reference-content' )
		.html( mainRef );
	if ( !mainRef ) {
		mainRefHtml.append( icons.spinner().$el );
	}
	const subRefHtml = props.isSubref ?
		util.parseHTML( '<div>' ).html( props.text ) : '';

	return new Drawer(
		util.extend(
			{
				showCollapseIcon: false,
				className: 'drawer position-fixed text references-drawer',
				events: {
					'click sup a': ( ev ) => {
						// Stop default scroll to hash fragment behaviour.
						ev.preventDefault();
					},
					'click sup': props.onNestedReferenceClick &&
						makeOnNestedReferenceClickHandler( props.onNestedReferenceClick )
				},
				children: [
					util.parseHTML( '<div>' )
						.addClass( 'references-drawer__header' )
						.append( [
							new Icon( {
								icon: 'reference',
								isSmall: true
							} ).$el,
							util.parseHTML( '<span>' ).addClass( 'references-drawer__title' ).text( mw.msg( 'mobile-frontend-references-citation' ) ),
							icons.cancel( 'gray', {
								isSmall: true
							} ).$el
						] ),

					// Add .mw-parser-output so that TemplateStyles styles apply (T244510)
					util.parseHTML( '<div>' ).addClass( 'mw-parser-output' ).append( [
						errorIcon,
						util.parseHTML( '<sup>' ).text( props.title ),
						mainRefHtml,
						subRefHtml
					] )
				]
			},
			props
		)
	);
}

/**
 * Internal for use inside Minerva only. See {@link module:mobile.startup} for access.
 *
 * @exports module:mobile.startup/references
 */
const references = {
	test: {
		makeOnNestedReferenceClickHandler
	},
	ReferencesHtmlScraperGateway,
	referenceDrawer,
	/**
	 * Fetch and render nested reference upon click
	 *
	 * @param {string} id of the reference to be retrieved
	 * @param {Page} page to locate reference for
	 * @param {string} refNumber the number it identifies as in the page
	 * @param {module:mobile.startup/PageHTMLParser} pageHTMLParser
	 * @param {module:mobile.startup/references~Gateway} gateway
	 * @param {Object} props for referenceDrawer
	 * @param {Function} onShowNestedReference function call when a nested reference is triggered.
	 * @return {jQuery.Deferred}
	 */
	showReference( id, page, refNumber, pageHTMLParser, gateway, props,
		onShowNestedReference
	) {
		return gateway.getReference( id, page, pageHTMLParser ).then( ( reference ) => {
			const drawer = referenceDrawer( util.extend( {
				title: refNumber,
				text: reference.text,
				parentText: reference.parentText,
				isSubref: reference.isSubref,
				onNestedReferenceClick( href, text ) {
					references.showReference(
						href,
						page,
						text,
						pageHTMLParser,
						gateway
					).then( ( nestedDrawer ) => {
						if ( props.onShowNestedReference ) {
							onShowNestedReference( drawer, nestedDrawer );
						} else {
							mw.log.warn( 'Please provide onShowNestedReferences parameter.' );
							document.body.appendChild( nestedDrawer.$el[0] );
							drawer.hide();
							nestedDrawer.show();
						}
					} );
				}
			}, props ) );
			return drawer;
		}, ( err ) => {
			// If non-existent reference nothing to do.
			if ( err === ReferencesGateway.ERROR_NOT_EXIST ) {
				return;
			}

			return referenceDrawer( {
				error: true,
				title: refNumber,
				text: mw.msg( 'mobile-frontend-references-citation-error' )
			} );
		} );
	}
};

module.exports = references;
const
	storageKey = 'mobileFrontend/toast';

/**
 * Show the previously saved toast data and delete it from storage
 *
 * @memberof Toast
 * @instance
 * @private
 */
function showPending() {
	let data = mw.storage.get( storageKey );
	if ( data ) {
		data = JSON.parse( data );
		mw.notify( data.content, data.options );
		mw.storage.remove( storageKey );
	}
}

mw.requestIdleCallback( showPending );

/**
 * Save the toast data in storage so that we can show it on page reload.
 * Also check whether there is a pending message that's not shown yet.
 * If yes, output a warning message and discard this message.
 * This is to ensure that the page needs to be reloaded before adding
 * a new message for showing later.
 *
 * @memberof Toast
 * @instance
 * @param {string} content Content to be placed in element
 * @param {Object|string} [options]
 *  If a string (deprecated) CSS class to add to the element
 *  If an object, more options for the notification see mw.notification.show.
 *  For backwards compatibility reasons if a string is given it will be
 *  treated as options.type
 */
function showOnPageReload( content, options ) {
	if ( mw.storage.get( storageKey ) ) {
		mw.log.warn(
			'A pending toast message already exits. ' +
				'The page should have been reloaded by now.'
		);
		return;
	}
	mw.storage.set( storageKey, JSON.stringify( {
		content,
		options
	} ) );
}

module.exports = { showOnPageReload };
const units = [ 'seconds', 'minutes', 'hours', 'days', 'months', 'years' ],
	util = require( './util' ),
	limits = [ 1, 60, 3600, 86400, 2592000, 31536000 ];

/**
 * Calculate the correct unit of timestamp
 *
 * @memberof module:mobile.startup/time
 * @instance
 * @param {number} timestampDelta
 * @return {{value: number, unit: string}}
 */
function timeAgo( timestampDelta ) {
	let i = 0;
	while ( i < limits.length && timestampDelta > limits[i + 1] ) {
		++i;
	}
	return {
		value: Math.round( timestampDelta / limits[i] ),
		unit: units[i]
	};
}

/**
 * Calculate the correct unit of timestamp delta
 *
 * @memberof module:mobile.startup/time
 * @param {number} timestamp
 * @return {{value: number, unit: string}}
 */
function getTimeAgoDelta( timestamp ) {
	const currentTimestamp = Math.round( Date.now() / 1000 );

	return timeAgo( currentTimestamp - timestamp );
}

/**
 * Whether timestamp delta is less than a day old
 *
 * @instance
 * @memberof module:mobile.startup/time
 * @param {{value: number, unit: string}} delta Object of timestamp and its label
 * @return {boolean}
 */
function isRecent( delta ) {
	return [ 'seconds', 'minutes', 'hours' ].includes( delta.unit );
}

/**
 * Is delta less than 10 seconds?
 *
 * @instance
 * @memberof module:mobile.startup/time
 * @param {{value: number, unit: string}} delta Object of timestamp and its label
 * @return {boolean}
 */
function isNow( delta ) {
	return delta.unit === 'seconds' && delta.value < 10;
}

/**
 * Return a message relating to the last modified relative time.
 *
 * @instance
 * @memberof module:mobile.startup/time
 * @param {number} ts timestamp
 * @param {string} username of the last user to modify the page
 * @param {string} gender of the last user to modify the page
 * @param {string} historyUrl url to the history page for the message (deprecated)
 * @return {string}
 */
function getLastModifiedMessage( ts, username, gender, historyUrl ) {
	const linkAll = typeof historyUrl === 'undefined',
		keys = {
			seconds: 'mobile-frontend-last-modified-with-user-seconds',
			minutes: 'mobile-frontend-last-modified-with-user-minutes',
			hours: 'mobile-frontend-last-modified-with-user-hours',
			days: 'mobile-frontend-last-modified-with-user-days',
			months: 'mobile-frontend-last-modified-with-user-months',
			years: 'mobile-frontend-last-modified-with-user-years'
		},
		args = [];

	gender = gender || 'unknown';

	const delta = getTimeAgoDelta( ts );
	if ( isNow( delta ) ) {
		args.push( 'mobile-frontend-last-modified-with-user-just-now', gender, username );
	} else {
		args.push( keys[ delta.unit ], gender, username,
			mw.language.convertNumber( delta.value )
		);
	}

	const lastEditedElement = linkAll ?
		util.parseHTML( '<strong>' ).attr( 'class', 'last-modified-text-accent' ) :
		util.parseHTML( '<a>' ).attr( 'href', historyUrl || '#' );
	const usernameElement = linkAll ?
		util.parseHTML( '<span>' ).attr( 'class', 'last-modified-text-accent' ) :
		util.parseHTML( '<a>' ).attr( 'href', mw.util.getUrl( 'User:' + username ) );

	args.push(
		lastEditedElement,
		// Abuse PLURAL support to determine if the user is anonymous or not
		mw.language.convertNumber( username ? 1 : 0 ),
		// Our abuse of PLURAL support means we have to pass the relative URL
		// rather than construct it from a wikilink
		username ? usernameElement : ''
	);

	return mw.message.apply( this, args ).parse();
}

/**
 * Return a message relating to the registration date of the user
 *
 * @instance
 * @memberof module:mobile.startup/time
 * @param {string} ts timestamp
 * @param {string} [gender] of the last user editing this page
 * @return {string}
 */
function getRegistrationMessage( ts, gender ) {
	const keys = {
		seconds: 'mobile-frontend-joined-seconds',
		minutes: 'mobile-frontend-joined-minutes',
		hours: 'mobile-frontend-joined-hours',
		days: 'mobile-frontend-joined-days',
		months: 'mobile-frontend-joined-months',
		years: 'mobile-frontend-joined-years'
	};

	const args = [];

	gender = gender || 'unknown';

	const delta = getTimeAgoDelta( parseInt( ts, 10 ) );
	if ( isNow( delta ) ) {
		args.push( 'mobile-frontend-joined-just-now', gender );
	} else {
		args.push( keys[ delta.unit ], gender, mw.language.convertNumber( delta.value ) );
	}
	const html = mw.message.apply( this, args ).parse();
	return html;
}

/**
 * Utility library for relative time.
 *
 * @exports module:mobile.startup/time
 */
module.exports = {
	getLastModifiedMessage,
	getRegistrationMessage,
	timeAgo,
	getTimeAgoDelta,
	isNow,
	isRecent
};
